//! Parity with the TypeScript engine: every case of `engines/fixtures/integrated.json`
//! (generated by `engines/fixtures/integrated.ts`) must produce the same bytes.

#![allow(clippy::panic)] // a test harness reports fixture problems by panicking

use serde_json::{Map, Value};
use sipges_analytics_common::js;

#[test]
fn every_case_matches_the_typescript_engine_byte_for_byte() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/integrated.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    let fixtures: Value = serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse: {e}"));
    let cases = fixtures
        .get("cases")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    assert!(cases.len() >= 7, "expected the full fixture set");
    let mut failures = Vec::new();
    for case in &cases {
        let field = |key: &str| case.get(key).and_then(Value::as_str).unwrap_or_default();
        let request: Map<String, Value> = serde_json::from_str(field("request"))
            .unwrap_or_else(|e| panic!("{}: request: {e}", field("name")));
        let actual = sipges_integrated::run(&request).map(|v| js::stringify(&v));
        if actual.as_deref() != Ok(field("value")) {
            failures.push(field("name").to_owned());
        }
    }
    assert!(
        failures.is_empty(),
        "cases differ from TypeScript: {failures:?}"
    );
}

#[test]
fn rejects_requests_outside_the_typescript_types() {
    let bad = |text: &str| {
        let request: Map<String, Value> = serde_json::from_str(text).unwrap_or_default();
        sipges_integrated::run(&request).map_err(|e| e.code())
    };
    assert_eq!(
        bad(r#"{"records":{},"generated_at":"x"}"#),
        Err("invalid_input")
    );
    assert_eq!(
        bad(r#"{"records":[],"project_id":"p","generated_at":"x"}"#),
        Err("invalid_input")
    );
    assert_eq!(
        bad(
            r#"{"records":{"Dialogos":[{"id":"d","payload":1}]},"project_id":"p","generated_at":"x"}"#
        ),
        Err("invalid_input")
    );
}
